={{
{
  "termo_busca": $fromAI('termo_busca', 'O nome, cor ou estilo que o cliente deseja. Ex: tenis, blusa preta. Deixe vazio se ele só pedir barato') || "",
  "preco_maximo": $fromAI('preco_maximo', 'Se o cliente pedir algo barato ou até X reais, extraia o número e coloque aqui. Se não houver limite, retorne null', 'number') || null,
  "categoria": $fromAI('categoria', 'Categoria identificada, como calçados, camisetas. Deixe vazio se não estiver claro') || ""
}
}}

={{
{
  "name": $fromAI('name', 'Nome do produto escolhido pelo usuário'),
  "description": $fromAI('description', 'Descrição detalhada do produto'),
  "price": $fromAI('price', 'Preço numérico do produto (apenas números ex: 99.90)', 'number') || null,
  "categoryId": $fromAI('categoryId', 'O ID exato (começa com cm...) retornado pela ferramenta de listar categorias'),
  "images": ($fromAI('images', 'Uma string contendo as URLs das fotos separadas apenas por vírgulas. Exemplo: url1,url2', 'string') || '').split(',').map(url => url.trim()).filter(Boolean),
  "sellerId": $('Webhook').item.json.body.sellerId,
  "quantity": $fromAI('quantity', 'Quantidade do produto em estoque (padrão 1)', 'number') || 1,
  "condition": $fromAI('condition', 'Estado do produto. Opções: NEW, USED_LIKE_NEW, USED_GOOD, USED_FAIR') || 'NEW',
  "priceType": "FIXED",
  "isService": false
}
}}
